/// Module: database / db1_create_database / domain / constants
///
///*************************** FILE INFO ****************************///
/// File Name: create_database_constants.dart
/// Purpose: Declares `CreateDatabaseLimits` and `CreateDatabaseStrings`.
/// Author: Knowticed Plus team
/// Created at: 15/8/2026
///
/// WHY THE STRINGS ARE HERE AND NOT IN l10n
/// ----------------------------------------
/// The app's normal channel is `S.of(context).someKey`, backed by
/// `lib/l10n/intl_en.arb` + `intl_ar.arb` and regenerated by flutter_intl.
/// This module's keys (createNewDatabase, databaseTitle, accessManagement,
/// restrictedAccess …) do not exist in those .arb files yet, and adding them
/// means a codegen run that has to happen on a machine with the Flutter SDK.
///
/// So the module ships its own en/ar table and resolves it with
/// `context.isArabic`, exactly the signal the rest of the app uses for RTL.
/// Migration path when you do run codegen: move each entry into the .arb
/// pair under the same key name and swap `CreateDatabaseStrings.of(context)`
/// for `S.of(context)`. Nothing outside this file needs to change.

import 'package:flutter/widgets.dart';

import 'package:knowticed_plus/core/extensions/context_extensions.dart';

/// Hard limits enforced by both the cubit and the text fields.
abstract final class CreateDatabaseLimits {
  /// Character ceiling on either description field — the "0/500" counter in
  /// the Figma card (7398:6196 / 7398:6197).
  static const int descriptionMaxLength = 500;

  /// Character ceiling on either title field.
  static const int titleMaxLength = 100;

  /// A title shorter than this is rejected as accidental.
  static const int titleMinLength = 2;
}

/// Firestore location for the created records. Kept in the module rather than
/// `core/constants/firebase_collections.dart` so the core file stays the
/// shared vocabulary and this module owns its own storage.
abstract final class CreateDatabaseCollections {
  /// Records collection, RELATIVE TO THE TENANT ROOT.
  ///
  /// MOVED 15/8/2026: this was the top-level collection `Databases`, which put
  /// every company's databases in one global bucket. It now lives under the
  /// tenant, the same shape the services module uses
  /// (`Modules/services/CreateServices`):
  ///
  ///     Demo/{companyId}/Modules/database_builder/Databases/{recordId}
  ///
  /// The path stays RELATIVE here on purpose. `getBaseUrl` prepends
  /// `Demo/{companyId}` from `ApiConstants.baseUri`, which is set at login —
  /// so the tenant is resolved in the data layer, and this domain-layer
  /// constant never has to know about a company id or import core/network.
  ///
  /// Note `Demo/{companyId}/Modules/database_builder` is a DOCUMENT, and it does not
  /// need to exist for the collection beneath it to work — Firestore is happy
  /// with a missing parent doc. It will show greyed-out in the console.
  static const String databases = 'Modules/database_builder/Databases';

  /// Subcollection under a database document holding its access grants.
  /// Nested under a document, so this one is NOT tenant-prefixed.
  static const String accessGrants = 'Access_Grants';

  /// Cloud STORAGE folder for cover images, also relative to the tenant root:
  /// `Demo/{companyId}/Modules/database_builder/covers/{timestamp}.{ext}`.
  ///
  /// Moved with the collection so one company's uploads are not mixed into
  /// another's. Already-uploaded covers keep working — records store the
  /// download URL, not the path.
  static const String coversFolder = 'Modules/database_builder/covers';
}

